def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_me = my[-1]
    last_op = op[-1]

    total_d = sum(1 for x in op if x == 'D')
    total_c = n - total_d

    if n < 4:
        if total_d == n:
            return 'D'
        return 'C'

    s10 = op[-10:]
    d10 = sum(1 for x in s10 if x == 'D')

    s20 = op[-20:]
    l20 = len(s20)
    d20 = sum(1 for x in s20 if x == 'D')
    c20 = l20 - d20

    myD10 = sum(1 for x in my[-10:] if x == 'D')

    trans = 0
    if l20 > 1:
        prev = s20[0]
        for x in s20[1:]:
            if prev == 'C' and x == 'D':
                trans += 1
            prev = x

    exploitable = (d20 <= 6 and trans <= 1 and total_d <= 6)

    if last_op == 'C' and exploitable and myD10 >= 2:
        return 'D'

    if last_op == 'C' and exploitable:
        for i in range(max(1, n - 12), n):
            if my[i - 1] == 'D' and op[i - 1] == 'C' and my[i] == 'C' and op[i] == 'C':
                return 'D'

    if (last_me == 'C' and last_op == 'C' and d10 <= 1 and d20 <= 4 and trans <= 1
        and total_d <= 4 and 25 <= n <= 94):
        if n == 30 or rng.random() < 0.015:
            return 'D'

    if last_op == 'D':
        if (n >= 4 and op[-1] == 'D' and op[-2] == 'D' and op[-3] == 'D' and op[-4] == 'D'
            and my[-1] == 'C' and my[-2] == 'C' and my[-3] == 'C' and my[-4] == 'C'
            and total_d <= 4 and c20 >= 8 and trans <= 1):
            return 'D'

        if (n >= 3 and last_me == 'C' and my[-2] == 'D' and op[-2] == 'C'
            and c20 >= 8 and d20 <= 6 and total_d <= 8 and trans <= 2):
            return 'C'

        if d20 <= 4 and c20 >= 8 and total_d <= 4 and (trans <= 1 or d10 <= 1 or d20 <= 2):
            return 'C'

        if d10 <= 1 and total_d <= 6 and total_c >= 3 * total_d:
            return 'C'

        if last_me == 'D' and c20 >= 12 and d20 <= 5 and myD10 <= 2 and trans <= 1:
            return 'C'

        return 'D'

    if last_me == 'D':
        return 'C'

    return 'C'
